python3 -c "
import plistlib

with open('raw/manifests/Info.plist', 'rb') as f:
    pl = plistlib.load(f)

for k in ['CFBundleIdentifier', 'CFBundleShortVersionString', 'CFBundleVersion', 'Device']:
    if k in pl:
        print(f'{k}: {pl[k]}')
for k, v in pl.items():
    if 'Build' in k or 'Train' in k or 'OS' in k or 'Device' in k:
        print(f'{k}: {v}')
"
